var configRes = await fetch("/config.json");
if (!configRes.ok) {
  app.innerHTML = "<p>La taquilla todav\xEDa no tiene contrato publicado.</p>";
} else {
  state.config = await configRes.json();
  state.client = createPublicClient({
    chain: {
      id: state.config.chainId,
      name: "Paseo",
      nativeCurrency: { name: "PAS", symbol: "PAS", decimals: 18 },
      rpcUrls: { default: { http: [state.config.rpc] } }
    },
    transport: http(state.config.rpc)
  });
  route().catch((error) => {
    app.innerHTML = `<p class="status">${esc(error.shortMessage || error.message)}</p>`;
  });
}
